1	import { db } from "./db";
2	
3	// Credits already cap spend per build, but nothing stops a broken or
4	// malicious client from firing many rapid requests before a human notices —
5	// and a free, unmetered *.kodely.site subdomain is a spam/phishing vector
6	// independent of credit spend. These are coarse, cheap safety nets, not a
7	// content-moderation system (there is no classifier here — a page can still
8	// be abusive content and pass both checks; that's a separate, harder problem
9	// left for a dedicated moderation pass, not faked here with a weak heuristic).
10	
11	const GENERATE_LIMIT = 20; // per user, per rolling hour
12	const PUBLISH_LIMIT = 15; // new (first-time) publishes per user, per rolling day
13	const ENHANCE_LIMIT = 40; // per user, per rolling hour
14	
15	export async function checkGenerateRateLimit(
16	  userId: string,
17	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
18	  const since = new Date(Date.now() - 60 * 60_000);
19	  const count = await db.build.count({
20	    where: { project: { userId }, createdAt: { gte: since } },
21	  });
22	  if (count < GENERATE_LIMIT) return { allowed: true };
23	  return { allowed: false, retryAfterSeconds: 3600 };
24	}
25	
26	export async function checkPublishRateLimit(
27	  userId: string,
28	): Promise<{ allowed: boolean; retryAfterSeconds?: number }> {
29	  const since = new Date(Date.now() - 24 * 60 * 60_000);
30	  // Counts DISTINCT projects touched by a publish in the window, not publish
31	  // events — republishing the same project repeatedly still counts once.
32	  // That's the right shape: the abuse case is many distinct spam subdomains,
33	  // not heavy iteration on one real site (which credits already gate).
34	  const count = await db.project.count({
35	    where: { userId, publishedAt: { gte: since } },
36	  });
37	  if (count < PUBLISH_LIMIT) return { allowed: true };
38	  return { allowed: false, retryAfterSeconds: 86_400 };
39	}
40	
41	// In memory, and synchronous, unlike the two checks above — an enhance leaves
42	// nothing in the database to count. It writes no files, creates no build row
43	// and charges no credits by design (see lib/enhance.ts), and a throwaway
44	// suggestion does not justify its own table. So this is per-process and resets
45	// on every deploy: a speed bump, exactly like the contact form's throttle, and
46	// the right weight for a call that costs a fraction of a cent. The real
47	// spending gate is still checkGenerateRateLimit plus the credit meter — those
48	// sit in front of the only thing here that costs real money.
49	//
50	// The ceiling is deliberately well above checkGenerateRateLimit's 20 builds an
51	// hour: enhancing several drafts before committing to one build is the whole
52	// point of the feature, and a limit that punished that would fight it.
53	const enhanceHits = new Map<string, number[]>();
54	
55	export function checkEnhanceRateLimit(userId: string): {
56	  allowed: boolean;
57	  retryAfterSeconds?: number;
58	} {
59	  const now = Date.now();
60	  const cutoff = now - 60 * 60_000;
61	  const recent = (enhanceHits.get(userId) ?? []).filter((t) => t > cutoff);
62	
63	  // Bound the map so a long-lived process can't accumulate one entry per user
64	  // forever. Clearing wholesale (rather than evicting) briefly resets everyone
65	  // — acceptable for a speed bump, and it never denies a legitimate request.
66	  if (enhanceHits.size > 5000) enhanceHits.clear();
67	
68	  if (recent.length >= ENHANCE_LIMIT) {
69	    enhanceHits.set(userId, recent);
70	    // Wait until the oldest hit in the window ages out, not a flat hour.
71	    return {
72	      allowed: false,
73	      retryAfterSeconds: Math.max(1, Math.ceil((recent[0] - cutoff) / 1000)),
74	    };
75	  }
76	
77	  recent.push(now);
78	  enhanceHits.set(userId, recent);
79	  return { allowed: true };
80	}
