1	import { db } from "@/lib/db";
2	import { verifyPassword, createSession } from "@/lib/auth";
3	
4	export const dynamic = "force-dynamic";
5	
6	export async function POST(req: Request) {
7	  const body = (await req.json().catch(() => null)) as
8	    | { email?: string; password?: string }
9	    | null;
10	  const email = body?.email?.trim().toLowerCase();
11	  const password = body?.password;
12	  if (!email || !password) {
13	    return Response.json({ error: "Enter your email and password." }, { status: 400 });
14	  }
15	
16	  const user = await db.user.findUnique({ where: { email } });
17	  // Constant-shape response whether or not the account exists, to avoid
18	  // leaking which emails are registered. A Google-only account has no local
19	  // password to check against — it never verifies here (correctly, they
20	  // must use "Continue with Google" instead).
21	  const ok = user?.passwordHash ? await verifyPassword(password, user.passwordHash) : false;
22	  if (!user || !ok) {
23	    return Response.json({ error: "Incorrect email or password." }, { status: 401 });
24	  }
25	
26	  await createSession(user.id);
27	  return Response.json({ id: user.id, email: user.email });
28	}
