1	import { db } from "@/lib/db";
2	import { hashPassword, createSession } from "@/lib/auth";
3	import { grantCredits, SIGNUP_GRANT } from "@/lib/credits";
4	import { createSeedProject } from "@/lib/seed-project";
5	import { track, EVENTS } from "@/lib/events";
6	
7	export const dynamic = "force-dynamic";
8	
9	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
10	
11	export async function POST(req: Request) {
12	  const body = (await req.json().catch(() => null)) as
13	    | { email?: string; password?: string; name?: string }
14	    | null;
15	
16	  const email = body?.email?.trim().toLowerCase();
17	  const password = body?.password;
18	
19	  if (!email || !EMAIL_RE.test(email)) {
20	    return Response.json({ error: "Enter a valid email." }, { status: 400 });
21	  }
22	  if (!password || password.length < 8) {
23	    return Response.json({ error: "Password must be at least 8 characters." }, { status: 400 });
24	  }
25	
26	  const existing = await db.user.findUnique({ where: { email } });
27	  if (existing) {
28	    return Response.json({ error: "An account with that email already exists." }, { status: 409 });
29	  }
30	
31	  const user = await db.user.create({
32	    data: { email, passwordHash: await hashPassword(password), name: body?.name?.trim() || null },
33	  });
34	
35	  await grantCredits(user.id, SIGNUP_GRANT, "signup_grant");
36	  await createSeedProject(user.id);
37	  await createSession(user.id);
38	
39	  track(EVENTS.signedUp, { userId: user.id, props: { method: "password" } });
40	
41	  return Response.json({ id: user.id, email: user.email });
42	}
