10	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
11	
12	export async function POST(req: Request) {
13	  const body = (await req.json().catch(() => null)) as
14	    | { email?: string; password?: string; name?: string }
15	    | null;
16	
17	  const email = body?.email?.trim().toLowerCase();
18	  const password = body?.password;
19	
20	  if (!email || !EMAIL_RE.test(email)) {
21	    return Response.json({ error: "Enter a valid email." }, { status: 400 });
22	  }
23	  if (!password || password.length < 8) {
24	    return Response.json({ error: "Password must be at least 8 characters." }, { status: 400 });
25	  }
26	
27	  // Deliberately AFTER the shape checks — a malformed body never created an
28	  // account, so there is nothing to meter — but BEFORE the existence check
29	  // below, which is the only response on this route that differs for a
30	  // registered address and is therefore an enumeration oracle. One counter now
31	  // bounds both that and the thing that actually costs money: every account
32	  // that lands here is immediately granted SIGNUP_GRANT credits of real model
33	  // spend. Keyed per client IP; see lib/rate-limit.ts for the header choice.
34	  const gate = checkSignupRateLimit(req);
35	  if (!gate.allowed) {
36	    return Response.json(
37	      { error: RATE_LIMITED_MESSAGE },
38	      {
39	        status: 429,
40	        headers: { "Retry-After": String(gate.retryAfterSeconds ?? 60) },
41	      },
42	    );
43	  }
44	
45	  const existing = await db.user.findUnique({ where: { email } });
46	  if (existing) {
47	    return Response.json({ error: "An account with that email already exists." }, { status: 409 });
48	  }
49	
50	  const user = await db.user.create({
51	    data: { email, passwordHash: await hashPassword(password), name: body?.name?.trim() || null },
52	  });
53	
54	  await grantCredits(user.id, SIGNUP_GRANT, "signup_grant");
55	  await createSeedProject(user.id);
56	  await createSession(user.id);
57	
58	  track(EVENTS.signedUp, { userId: user.id, props: { method: "password" } });
59	
60	  return Response.json({ id: user.id, email: user.email });
61	}
